DROP TABLE IF EXISTS `msalary`;
CREATE TABLE `msalary`  (
  `Eno` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '员工工号',
  `Smonth` varchar(7) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '月份',
  `baseS` decimal(10, 2) NULL DEFAULT NULL COMMENT '基础工资',
  `Oall` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '加班津贴',
  `Ade` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '考勤扣款',
  `grossS` decimal(10, 2) NULL DEFAULT NULL COMMENT '应发工资',
  `aaS` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '年度累计收入（工资 + 津贴累加）',
  `aa_de` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '年度累计扣除（5000×N + 专项附加 ×N），N是月份',
  `tax` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '当月个税',
  `netS` decimal(10, 2) NOT NULL COMMENT '实际工资（grossS - tax）',
  `aa_tax` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '年度累计个税（累加 tax）',
  PRIMARY KEY (`Eno`, `Smonth`) USING BTREE,
  CONSTRAINT `fk_msalary_emp_info` FOREIGN KEY (`Eno`) REFERENCES `emp_info` (`Eno`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

